"use client"

import { useMemo } from "react"

import { withForm } from "@/components/openlmis/form-fields/form"

import {
  categoryLabel,
  EMPTY_REASON,
  REASON_CATEGORIES,
  REASON_TYPES,
  TAG_REFUSALS,
  toCodeItems,
  typeLabel,
} from "@/components/blocks/openlmis/reason-general-form/reason-form"

export type ReasonLookups = {
  /** Category codes; defaults to the four OpenLMIS ships. */
  categories?: readonly string[]
  /** Type codes; defaults to Credit, Debit and Balance Adjustment. */
  types?: readonly string[]
  /** Tags other reasons use, suggested as the user types. */
  tags?: readonly string[]
}

type ReasonFormFieldsProps = {
  lookups?: ReasonLookups
  /** A saved reason keeps its category and type, so both are read only. */
  saved?: { category: string; type: string }
  readOnly?: boolean
}

const DEFAULT_CATEGORIES = Object.keys(REASON_CATEGORIES)
const DEFAULT_TYPES = Object.keys(REASON_TYPES)
const NO_TAGS: readonly string[] = []
const NO_LOOKUPS: ReasonLookups = {}

/** The reason's name, tags, category, type and free text, shared by Add Reason and the editor. */
export const ReasonFormFields = withForm({
  defaultValues: EMPTY_REASON,
  props: {} as ReasonFormFieldsProps,
  render: function Render({
    form,
    lookups = NO_LOOKUPS,
    saved,
    readOnly = false,
  }) {
    const {
      categories = DEFAULT_CATEGORIES,
      types = DEFAULT_TYPES,
      tags = NO_TAGS,
    } = lookups
    const categoryItems = useMemo(
      () => toCodeItems(categories, categoryLabel, saved?.category),
      [categories, saved?.category]
    )
    const typeItems = useMemo(
      () => toCodeItems(types, typeLabel, saved?.type),
      [types, saved?.type]
    )

    return (
      <div className="grid grid-cols-1 gap-x-6 gap-y-5 @3xl/main:grid-cols-2">
        <form.AppField name="name">
          {(field) => (
            <field.TextField
              autoComplete="off"
              dir="auto"
              disabled={readOnly}
              label="Name"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="tags">
          {(field) => (
            <field.TagsField
              description="Tags group reasons for other screens; their meaning is up to your team. Press Enter or a comma to add one."
              disabled={readOnly}
              label="Tags"
              maxLength={255}
              minLength={3}
              placeholder="Add A Tag"
              refusedMessage={(reason) => TAG_REFUSALS[reason]}
              removeLabel={(tag) => `Remove ${tag}`}
              suggestions={tags}
            />
          )}
        </form.AppField>
        <form.AppField name="category">
          {(field) => (
            <field.SelectField
              description={
                saved
                  ? "A saved reason keeps its category and type."
                  : undefined
              }
              disabled={readOnly || Boolean(saved)}
              items={categoryItems}
              label="Category"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="type">
          {(field) => (
            <field.SelectField
              disabled={readOnly || Boolean(saved)}
              items={typeItems}
              label="Type"
              required
            />
          )}
        </form.AppField>
        <form.AppField name="isFreeTextAllowed">
          {(field) => (
            <field.SwitchField
              description="Let users type a note when they pick this reason."
              disabled={readOnly}
              label="Allow Free Text"
            />
          )}
        </form.AppField>
      </div>
    )
  },
})

import { z } from "zod"

import type { TagRefusal } from "@/components/openlmis/form-fields/tags"

/** Why stock moved, as OpenLMIS groups reasons; a code the server adds later shows as it is. */
export const REASON_CATEGORIES: Record<string, string> = {
  TRANSFER: "Transfer",
  ADJUSTMENT: "Adjustment",
  PHYSICAL_INVENTORY: "Physical Inventory",
  AGGREGATION: "Aggregation",
}

/** Whether the reason adds stock, takes it away, or corrects it. */
export const REASON_TYPES: Record<string, string> = {
  CREDIT: "Credit",
  DEBIT: "Debit",
  BALANCE_ADJUSTMENT: "Balance Adjustment",
}

export const categoryLabel = (code: string) => REASON_CATEGORIES[code] ?? code
export const typeLabel = (code: string) => REASON_TYPES[code] ?? code

/** What the reason forms show and save; map your API's reason onto it. */
export type ReasonValues = {
  name: string
  category: string
  type: string
  isFreeTextAllowed: boolean
  tags: string[]
}

export const EMPTY_REASON: ReasonValues = {
  name: "",
  category: "",
  type: "",
  isFreeTextAllowed: false,
  tags: [],
}

const sameName = (a: string, b: string) =>
  a.trim().localeCompare(b.trim(), undefined, { sensitivity: "accent" }) === 0

/** `takenNames` holds other reasons' names, and any the server refused. */
export function reasonFormSchema(takenNames: readonly string[] = []) {
  return z.object({
    name: z
      .string()
      .trim()
      .min(1, "Enter a name.")
      .refine(
        (name) => !takenNames.some((other) => sameName(other, name)),
        "Another reason already has this name."
      ),
    category: z.string().min(1, "Choose a category."),
    type: z.string().min(1, "Choose a type."),
    isFreeTextAllowed: z.boolean(),
    tags: z.array(z.string()),
  })
}

export const toReasonValues = (values: ReasonValues): ReasonValues => ({
  ...values,
  name: values.name.trim(),
})

/** How many fields differ from the saved reason. */
export function reasonChanges(values: ReasonValues, saved: ReasonValues) {
  return [
    values.name.trim() !== saved.name.trim(),
    values.category !== saved.category,
    values.type !== saved.type,
    values.isFreeTextAllowed !== saved.isFreeTextAllowed,
    values.tags.join("\n") !== saved.tags.join("\n"),
  ].filter(Boolean).length
}

export const TAG_REFUSALS: Record<TagRefusal, string> = {
  "too-short": "A tag needs at least 3 characters.",
  "too-long": "A tag can have at most 255 characters.",
  duplicate: "This tag is already added.",
}

/** The codes as a select lists them, with a saved code the list lacks kept on the end. */
export function toCodeItems(
  codes: readonly string[],
  label: (code: string) => string,
  current?: string
) {
  const all = current && !codes.includes(current) ? [...codes, current] : codes
  return all.map((code) => ({ value: code, label: label(code) }))
}

"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { useEffect, useId, useMemo, useRef } from "react"

import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import { FieldSkeleton } from "@/components/openlmis/form-fields/form-fields"

import {
  reasonChanges,
  reasonFormSchema,
  type ReasonValues,
  toReasonValues,
} from "@/components/blocks/openlmis/reason-general-form/reason-form"
import { type ReasonLookups, ReasonFormFields } from "@/components/blocks/openlmis/reason-general-form/reason-form-fields"

type ReasonGeneralFormProps = {
  /** The reason's values, or `EMPTY_REASON` to add one; a skeleton shows until it is set. */
  reason: ReasonValues | undefined
  /** Whether the reason is stored, which fixes its category and type. */
  saved?: boolean
  lookups?: ReasonLookups
  /** Other reasons' names, and any the server refused, turned down as this one's. */
  takenNames?: readonly string[]
  readOnly?: boolean
  /** The form's id, for a Save placed elsewhere, e.g. in a page's `WorkspaceFooter`. */
  formId?: string
  /** Called with trimmed values once every field is valid. */
  onSubmit: (values: ReasonValues) => void
  /** Called when a submit finds errors. */
  onInvalid?: () => void
  /** Tells the page how many fields are unsaved, e.g. to ask before leaving. */
  onChangesChange?: (changes: number) => void
}

/** A stock reason's details: name, tags, category, type and free text. */
export function ReasonGeneralForm({
  reason,
  ...props
}: ReasonGeneralFormProps) {
  if (!reason) return <ReasonGeneralFormSkeleton />
  return <GeneralForm reason={reason} {...props} />
}

function GeneralForm({
  reason,
  saved = false,
  lookups,
  takenNames,
  readOnly = false,
  formId: givenFormId,
  onSubmit,
  onInvalid,
  onChangesChange,
}: ReasonGeneralFormProps & { reason: ReasonValues }) {
  const generatedFormId = useId()
  const formId = givenFormId ?? generatedFormId
  // Keyed on the names, so an inline array does not re-run validation each render.
  const takenKey = takenNames?.join("\n") ?? ""
  const schema = useMemo(
    () => reasonFormSchema(takenKey ? takenKey.split("\n") : []),
    [takenKey]
  )

  const form = useAppForm({
    defaultValues: reason,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(toReasonValues(value)),
    onSubmitInvalid: () => onInvalid?.(),
  })
  const changes = useStore(form.store, (state) =>
    reasonChanges(state.values, reason)
  )

  // Starts again only when the values differ, so an equal new object keeps the draft.
  const reasonKey = JSON.stringify(reason)
  const resetKey = useRef(reasonKey)
  useEffect(() => {
    if (resetKey.current === reasonKey) return
    resetKey.current = reasonKey
    form.reset(reason)
  }, [form, reason, reasonKey])
  // A name the server refused shows its error at once, rather than on the next submit.
  useEffect(() => {
    if (form.state.submissionAttempts === 0) return
    form.update({ ...form.options, validators: { onDynamic: schema } })
    void form.validate("change")
  }, [form, schema])
  useEffect(() => {
    onChangesChange?.(changes)
  }, [changes, onChangesChange])

  return (
    <form
      id={formId}
      noValidate
      onSubmit={(event) => {
        event.preventDefault()
        void form.handleSubmit()
      }}
    >
      <FieldGroup>
        <ReasonFormFields
          form={form}
          lookups={lookups}
          readOnly={readOnly}
          saved={saved ? reason : undefined}
        />
      </FieldGroup>
    </form>
  )
}

/** The form as it will look, so nothing moves when the reason arrives. */
export function ReasonGeneralFormSkeleton() {
  return (
    <div aria-busy>
      <FieldGroup>
        <div className="grid grid-cols-1 gap-x-6 gap-y-5 @3xl/main:grid-cols-2">
          <FieldSkeleton label="Name" required />
          <FieldSkeleton label="Tags" />
          <FieldSkeleton label="Category" required />
          <FieldSkeleton label="Type" required />
          <Field orientation="horizontal">
            <div className="flex min-h-8 flex-1 items-center">
              <FieldLabel>Allow Free Text</FieldLabel>
            </div>
            {/* A plain element, since Skeleton owns its corner radius and the switch is round. */}
            <div className="h-4.5 w-8 shrink-0 animate-pulse rounded-full bg-muted" />
          </Field>
        </div>
      </FieldGroup>
    </div>
  )
}
